local config = {
  ui_story_40180001_1_dialog_content = "Let one who possesses complete mastery over the truth speak first—that is to say, me.",
  ui_story_40180001_2_dialog_content = "However, as a noble aristocrat of Lumopolis, this matter should surely be handled by me.",
  ui_story_40180001_3_dialog_content = "What are you arguing about, children? Of course, something like this should be left in the hands of an adult. Allow me.",
  ui_story_40180001_4_dialog_content = "Wait, wait, wait...",
  ui_story_40180001_5_dialog_content = "I know I said I wanted to hear a bedtime story...",
  ui_story_40180001_6_dialog_content = "But I didn't expect this level of enthusiasm...",
  ui_story_40180001_7_dialog_content = "<size=36>The truth above all else!</size>",
  ui_story_40180001_8_dialog_content = "<size=40>Trust in nobility!</size>",
  ui_story_40180001_9_dialog_content = "<size=44>Seniority must take precedence!</size>",
  ui_story_40180001_10_dialog_content = "(What a headache... If I had known this would happen, I wouldn't have bothered calling these three.)",
  ui_story_40180001_11_dialog_content = "(The stories they told me before were so interesting, but now they're tripping over each other to tell me one...)",
  ui_story_40180001_12_dialog_content = "Speak up, Snowball. Tell us—who should tell their story first?",
  ui_story_40180001_13_dialog_content = "Of course, whoever has the best story should go first.",
  ui_story_40180001_14_dialog_content = "Well, PlayerName wants to hear a bedtime story. If it's too exciting, he won't be able to sleep.",
  ui_story_40180001_15_dialog_content = "So, whoever's story is the most boring should be told last, in order to send him soundly to sleep.",
  ui_story_40180001_16_dialog_content = "If that's how it is, how can I refuse. I shall go first...",
  ui_story_40180001_17_dialog_content = "Wait, if whoever has the best story must go first...",
  ui_story_40180001_18_dialog_content = "It should clearly be me!",
  ui_story_40180001_19_dialog_content = "I once told you a fantastic story about a tomb raider. Do you remember, Snowball?",
  ui_story_40180001_20_dialog_content = "Oh, that... I...",
  ui_story_40180001_21_dialog_content = "Hey, I also told the Navigator an amazing story about the noble spirit of my ancestors.",
  ui_story_40180001_22_dialog_content = "It seems you youngsters have learned well from your elders. What a coincidence... I also told the Navigator a marvelously curious hunting story.",
  ui_story_40180001_23_dialog_content = "It appears we have a dilemma on our hands. We'd better let PlayerName decide.",
  ui_story_40180001_24_dialog_content = "PlayerName, who do you think told the best story last time? That person should tell the first story tonight. What do you think?",
  ui_story_40180001_25_dialog_content = "I... I...",
  ui_story_40180001_26_dialog_content = "To be honest, I've forgotten most of what you all told me...",
  ui_story_40180001_27_dialog_content = "What a terrible slight! Forgotten, you say!?",
  ui_story_40180001_28_dialog_content = "Please, don't be angry... Why don't you help me remember them again?",
  ui_story_40180001_29_dialog_content = "Let me see. The three stories were...",
  ui_story_40180001_30_option_content = "What was Sikare Dantes'?",
  ui_story_40180001_31_dialog_content = "My little Snowball, have you truly forgotten? I once caught a tomb raider and asked him to tell me his tales for ten days and ten nights.",
  ui_story_40180001_32_dialog_content = "One of the stories was about a time he lost his way in Northland Forest. He met a strange child who led him out of the forest.",
  ui_story_40180001_33_dialog_content = "I liked this story very much, so in return, I gave the tomb raider a most precious treasure.",
  ui_story_40180001_34_dialog_content = "And it was the truth.",
  ui_story_40180001_35_dialog_content = "The story about treasures... Yes.",
  ui_story_40180001_36_option_content = "And Beverly's?",
  ui_story_40180001_37_dialog_content = "Do you remember, PlayerName? You asked me about the spirit of the nobility.",
  ui_story_40180001_38_dialog_content = "I told you about my ancestors' expedition to Northland.",
  ui_story_40180001_39_dialog_content = "They defeated the Eclipsites there and rescued the villagers. Although they took heavy casualties, they fulfilled their aristocratic obligations.",
  ui_story_40180001_40_dialog_content = "However, they did not accept the food and water offered to them by the villagers, exemplifying the difference between you and I.",
  ui_story_40180001_41_dialog_content = "Now that you mention it, I seem to recall the story.",
  ui_story_40180001_42_option_content = "And Constantine's story?",
  ui_story_40180001_43_dialog_content = "My child, I told you a story about hunting Eclipsites. Do you remember?",
  ui_story_40180001_44_dialog_content = "While hunting in Northland Forest, I ran into a strange creature.",
  ui_story_40180001_45_dialog_content = "I thought it was an Eclipsite, but after chasing it for three hours, I discovered that it was a <color=#FFB400>child</color>.",
  ui_story_40180001_46_dialog_content = "The child wasn't wearing much, and didn't want to go home, so I gave the child my <color=#FFB400>coat</color>.",
  ui_story_40180001_47_dialog_content = "Then I <color=#FFB400>escorted the child out of the forest</color> and was going to take the child home, but the disobedient child ran away.",
  ui_story_40180001_48_dialog_content = "The child didn't even take the coat! I was so worried that the poor child would catch a cold!",
  ui_story_40180001_49_dialog_content = "This story... was kind of weird.",
  ui_story_40180001_50_dialog_content = "Well, I remember all three stories now.",
  ui_story_40180001_51_dialog_content = "The stories were all very interesting... but they're not really bedtime story material.",
  ui_story_40180001_52_dialog_content = "As for now... it's really difficult for me to choose someone to go first.",
  ui_story_40180001_53_dialog_content = "But anyway, if I must choose someone, it'll have to be...",
  ui_story_40180001_54_dialog_content = "Hold on!",
  ui_story_40180001_55_dialog_content = "What?",
  ui_story_40180001_56_dialog_content = "Wait, PlayerName... You can choose later.",
  ui_story_40180001_57_dialog_content = "I've suddenly realized something quite terrifying...",
  ui_story_40180001_58_dialog_content = "Erm... What—!?",
  ui_story_40180001_59_dialog_content = "Sikare and Constantine both told stories about... <color=#FFB400>a child of Northland</color>...",
  ui_story_40180001_60_dialog_content = "Huh? Yeah, that's true...",
  ui_story_40180001_61_dialog_content = "Both Constantine and the tomb raider Sikare mentioned having met a child in Northland Forest, and then...",
  ui_story_40180001_X61_dialog_content = "<color=#FFB400>They walked out of the forest with the child</color>.",
  ui_story_40180001_62_dialog_content = "Correct?",
  ui_story_40180001_63_dialog_content = "That's it.",
  ui_story_40180001_64_dialog_content = "Yes, and the child left behind my coat...",
  ui_story_40180001_65_dialog_content = "The coat isn't the point here... I actually heard the same story <color=#FFB400>in the village where my ancestors went on their expedition</color>!",
  ui_story_40180001_66_dialog_content = "What?!",
  ui_story_40180001_67_dialog_content = "What? Did you see that child, too? Did the child have a cold...?",
  ui_story_40180001_68_dialog_content = "Whether he had a cold or not isn't the point, either!",
  ui_story_40180001_69_dialog_content = "A while ago, I went to Northland—to the village where my ancestors once journeyed.",
  ui_story_40180001_70_dialog_content = "I went to visit the descendants of those villagers and, on behalf of my ancestors, received their gifts of food and water.",
  ui_story_40180001_71_dialog_content = "Then we chatted happily, and the villagers told me some strange tales about Northland, including...",
  ui_story_40180001_X71_dialog_content = "<color=#FFB400>A tale about a strange child in Northland Forest</color>.",
  ui_story_40180001_72_dialog_content = "What? Recently? That child's still going to the forest to play? What a naughty kid...",
  ui_story_40180001_73_dialog_content = "And then what happened!? Tell me!",
  ui_story_40180001_74_dialog_content = "Beverly, what did the villagers of Northland tell you?",
  ui_story_40180001_75_dialog_content = "They said that, just last month, a villager got lost in <color=#FFB400>Northland Forest</color> and couldn't find his way out.",
  ui_story_40180001_76_dialog_content = "He tried heading in every direction, and found nothing but a sea of trees wherever he turned.",
  ui_story_40180001_77_dialog_content = "He wandered around until it was so dark that he could no longer see the road clearly.",
  ui_story_40180001_A1_dialog_content = "And so the lost villager sat on the ground in despair, believing that he was going to die alone in the forest.",
  ui_story_40180001_78_dialog_content = "To tell you the truth... I heard he even began to cry. He was a strong man, but was still just a common civilian, after all.",
  ui_story_40180001_79_dialog_content = "And then!? What happened to him?",
  ui_story_40180001_80_dialog_content = "Then... as he cried, he thought of his child waiting for him at home.",
  ui_story_40180001_81_dialog_content = "His wife had passed away, and his child had no one else. He thought of how he would never escape the forest, and how his child would not only have no mother, but also no father...",
  ui_story_40180001_A2_dialog_content = "He fell into a pit of despair and began to call out his child's name.",
  ui_story_40180001_82_dialog_content = "But unexpectedly, as he called out... his child called back to him!",
  ui_story_40180001_83_dialog_content = "What?!",
  ui_story_40180001_84_dialog_content = "Shocked, he looked back and saw <color=#FFB400>his child</color> emerge from the dense forest.",
  ui_story_40180001_85_dialog_content = "And... the child was wearing a <color=#FFB400>strange coat</color>, just like the one Constantine is wearing right now.",
  ui_story_40180001_86_dialog_content = "What?!",
  ui_story_40180001_87_dialog_content = "That child discarded my coat, and then crafted one that looked exactly the same!?",
  ui_story_40180001_88_dialog_content = "Ah... that little thing must have thrown that coat back at me in case I should suffer from the cold.",
  ui_story_40180001_89_dialog_content = "I should... I should bring the child something more suitable... Why didn't I realize... I'm going to order one right now!",
  ui_story_40180001_90_dialog_content = "That child... Beverly, go on! <color=#FFB400>That child</color>, and the villager!",
  ui_story_40180001_91_dialog_content = "The villager... Of course, he was shocked to say the least.",
  ui_story_40180001_92_dialog_content = "He blurted out his child's name and ran over to hug him.",
  ui_story_40180001_93_dialog_content = "A stream of tears flowed uncontrollably from his eyes, melting the snow on the forest floor.",
  ui_story_40180001_94_dialog_content = "The child hugged him happily, yelling \"father\" in excitement and saying, \"I wanted to go home with you.\"",
  ui_story_40180001_95_dialog_content = "The villager was so excited that he couldn't even answer. He just kept nodding, then stood up as the child embraced him.",
  ui_story_40180001_96_dialog_content = "Then, they held hands and walked forward, one step at a time.",
  ui_story_40180001_97_dialog_content = "Before long, <color=#FFB400>they made it out of the forest</color>.",
  ui_story_40180001_98_dialog_content = "Once out of the forest, the villager knew his way back home. He was overjoyed, and went to pick up his child in celebration.",
  ui_story_40180001_99_dialog_content = "But as he turned to face him, he suddenly discovered something...",
  ui_story_40180001_100_dialog_content = "<anim type=Shake><color=#FFB400>No one stood beside him. He was surrounded by nothing but white snow...</color></anim> Like this?",
  ui_story_40180001_101_dialog_content = "Yes! How did you know?",
  ui_story_40180001_102_dialog_content = "Because that's exactly what the tomb raider said.",
  ui_story_40180001_103_dialog_content = "He was led out of the forest by a strange child, and when he turned to thank the child, he found nothing and no one.",
  ui_story_40180001_104_dialog_content = "<anim type=Shake><color=#FFB400>He couldn't even find the child's footprints</color></anim>.",
  ui_story_40180001_105_dialog_content = "It's just as I thought! So many people have met this child!",
  ui_story_40180001_106_dialog_content = "That seems to be the case.",
  ui_story_40180001_107_dialog_content = "Wait... Could it be mass hysteria? A shared hallucination or something?",
  ui_story_40180001_108_dialog_content = "It's so cold in the forest—it is possible that one might collapse after losing their way and experience such delusions.",
  ui_story_40180001_109_dialog_content = "What you say is possible, my little Snowball, however...",
  ui_story_40180001_110_dialog_content = "Constantine <color=#FFB400>actually met</color> this child himself.",
  ui_story_40180001_111_dialog_content = "It's absolutely true... That disobedient child...",
  ui_story_40180001_112_dialog_content = "Well, I have my doubts as to whether this child is real...",
  ui_story_40180001_A3_dialog_content = "The tomb raider and the villagers you met didn't make it up... And it wasn't a hallucination Constantine suffered after killing too many Eclipsites...",
  ui_story_40180001_113_dialog_content = "Hey! How could it have been a hallucination!? I took off my coat and put it on the child! I touched the child with my own hands!",
  ui_story_40180001_114_dialog_content = "Alright... But I still have my doubts.",
  ui_story_40180001_115_dialog_content = "Beverly, you just said that the child in the story was the villager's own child...",
  ui_story_40180001_116_dialog_content = "Oh... Yes, that is true.",
  ui_story_40180001_117_dialog_content = "This point is relatively easy to understand. It's normal for one to mistake a child for their own under the stress of such strong yearning and desperation.",
  ui_story_40180001_118_dialog_content = "If you look at it that way, it makes sense...",
  ui_story_40180001_119_dialog_content = "But it really is very strange!",
  ui_story_40180001_120_dialog_content = "If I recall correctly, Constantine said that Northland Forest was <color=#FFB400>devoid of human life</color>.",
  ui_story_40180001_121_dialog_content = "How could a child possibly be out there all alone?",
  ui_story_40180001_122_dialog_content = "That's right, and judging from the tales of this child helping others, and <color=#FFB400>leading the way out</color> three times...",
  ui_story_40180001_123_dialog_content = "Three times? Wasn't it only two times—the tomb raider and the villager?",
  ui_story_40180001_124_dialog_content = "In my case, I escorted the child home.",
  ui_story_40180001_125_dialog_content = "No matter how many times... This child must be very familiar with the paths of the forest.",
  ui_story_40180001_126_dialog_content = "More familiar than the tomb raider or the villager.",
  ui_story_40180001_127_dialog_content = "Yes. The tomb raider I met <color=#FFB400>even left markings while walking</color>. He was a very experienced traveler, indeed.",
  ui_story_40180001_128_dialog_content = "But he also ended up lost.",
  ui_story_40180001_129_dialog_content = "The villager also <color=#FFB400>tried walking in every direction</color>, but couldn't find a way out.",
  ui_story_40180001_130_dialog_content = "So... It's not so much that the strange child was very familiar with the roads in the forest...",
  ui_story_40180001_131_dialog_content = "It's more a case of...",
  ui_story_40180001_132_option_content = "The child came from nowhere to help those lost travelers?",
  ui_story_40180001_133_dialog_content = "Hey, I saw that child... and the child didn't have wings!",
  ui_story_40180001_134_option_content = "Maybe the child was dug holes out?",
  ui_story_40180001_135_dialog_content = "Hey, I saw that child... and there was no shovel!",
  ui_story_40180001_136_dialog_content = "This is strange... Very strange, indeed...",
  ui_story_40180001_137_dialog_content = "Yes, I believe it is very strange.",
  ui_story_40180001_138_dialog_content = "Even when no way out could be found, <color=#FFB400>the child led those lost people out of the forest</color>...",
  ui_story_40180001_139_dialog_content = "And when the villagers saw the child, the child really was <color=#FFB400>wearing Constantine's strange coat</color>...",
  ui_story_40180001_140_dialog_content = "How could a child create a perfect replica of such a unique item of clothing in a deserted, lifeless forest?",
  ui_story_40180001_141_dialog_content = "Exactly... That child would have had to have gone to great lengths in order to create such a coat...",
  ui_story_40180001_142_dialog_content = "Might have even pricked little finger while sewing on the buttons...",
  ui_story_40180001_143_dialog_content = "<size=42>That's not what we're getting at!</size>",
  ui_story_40180001_144_dialog_content = "The materials, the style... <color=#FFB400>How could a child make such clothes</color>? And clothes so very much alike Constantine's, nonetheless! That is the issue here!",
  ui_story_40180001_145_dialog_content = "So, there is definitely something not right about this child... No! <color=#FFB400>This child is the very source of all that is not right here</color>!",
  ui_story_40180001_146_dialog_content = "Ah... Beverly, please try to maintain your aristocratic grace!",
  ui_story_40180001_147_dialog_content = "Don't let this old man's strange ramblings cause you to lose yourself.",
  ui_story_40180001_148_dialog_content = "I'm sorry. I lost my head.",
  ui_story_40180001_149_dialog_content = "In fact, as this old man was the only one to make <color=#FFB400>direct contact</color> with the child, I wanted to ask him...",
  ui_story_40180001_150_dialog_content = "What do you want to know? That child actually looked quite handy. I'm not surprised that the child knows how to make clothes...",
  ui_story_40180001_151_dialog_content = "No, there's no point in asking you.",
  ui_story_40180001_152_dialog_content = "Why don't you ask someone else? If they're from Northland, they may have heard of him...",
  ui_story_40180001_153_dialog_content = "My little Snowball, do you know anyone from Northland?",
  ui_story_40180001_154_dialog_content = "Have they heard of any strange legends like this?",
  ui_story_40180001_155_dialog_content = "Let me think...",
  ui_story_40180001_156_option_content = "Queen Bethlehem?",
  ui_story_40180001_157_dialog_content = "If anyone knows about this, it'll be her... But she probably doesn't have time to hear us out.",
  ui_story_40180001_158_option_content = "And what about Constantine?",
  ui_story_40180001_159_dialog_content = "Don't you understand, my little Snowball? It's impossible to communicate with this strange old fool who seems perpetually fixated on overcoats!",
  ui_story_40180001_160_dialog_content = "Ah... Well...",
  ui_story_40180001_161_dialog_content = "Well, how about asking Louise?",
  ui_story_40180001_162_dialog_content = "You might consider my thinking to be strange... But I'd also like to know what happened to that child.",
  ui_story_40180001_163_dialog_content = "Louise likes learning about all kinds of legends. She should know, too.",
  ui_story_40180001_164_dialog_content = "Alright, I'll go find her.",
  ui_story_40180001_165_dialog_content = "Understood.",
  ui_story_40180001_166_dialog_content = [[
The tomb raider Sikare met, the villager Beverly heard of, and even Constantine himself, all ran into something strange in Northland Forest...
What a peculiar phenomenon...]],
  ui_story_40180001_167_dialog_content = "The tomb raider and the villager lost their way in the forest. They thought they'd never make it out, but they were led out of the forest by a child, who suddenly appeared out of nowhere.",
  ui_story_40180001_168_dialog_content = "Constantine, on the other hand, wanted to escort the strange child home. But it turns out he was probably lost too, and just didn't know it...",
  ui_story_40180001_169_dialog_content = "So now everybody wants to know <color=#FFB400>who this kid is</color>, right?",
  ui_story_40180001_170_dialog_content = "Oh, yeah!",
  ui_story_40180001_171_dialog_content = "I asked the three of them to tell me a bedtime story... because I couldn't sleep.",
  ui_story_40180001_172_dialog_content = "And because of this mess, there's really no way I'll be able to get to sleep now!",
  ui_story_40180001_173_dialog_content = "If you don't know the truth about this child... I'll probably be up till the crack of dawn thinking about it!",
  ui_story_40180001_174_dialog_content = "I see.",
  ui_story_40180001_175_dialog_content = "Well, unfortunately... I'm afraid you're going to be up till dawn, then.",
  ui_story_40180001_176_dialog_content = "What? Y-You mean...",
  ui_story_40180001_177_dialog_content = "This child... It's true that he features in the <color=#FFB400>legends of Northland</color>.",
  ui_story_40180001_178_dialog_content = "People often find themselves lost in the deepest depths of Northland Forest.",
  ui_story_40180001_179_dialog_content = "Whether it's a well-prepared traveler with a compass and map, a skilled Eclipsite hunter, or even the noble Queen Bethlehem...",
  ui_story_40180001_180_dialog_content = "If you enter that forest, you won't be able to leave.",
  ui_story_40180001_181_dialog_content = "It's because the paths in that forest are constantly changing, as though they are alive.",
  ui_story_40180001_182_dialog_content = "Changing?",
  ui_story_40180001_183_dialog_content = "Yes. Every minute, every second, every moment—every path is changing.",
  ui_story_40180001_184_dialog_content = "Those who step into the forest lose their way, lose all sense of direction, and then fall into despair.",
  ui_story_40180001_185_dialog_content = "That's horrible!",
  ui_story_40180001_186_dialog_content = "Fortunately, a benevolent child lives in that forest. No one knows where the child came from...",
  ui_story_40180001_187_dialog_content = "A lovely, outgoing, and very friendly child.",
  ui_story_40180001_188_dialog_content = "When travelers find themselves in despair, the child appears and the paths stop changing.",
  ui_story_40180001_189_dialog_content = "The child takes the lost traveler by the hand and leads them out of the forest.",
  ui_story_40180001_190_dialog_content = "The child leads them to see the snow plains, Lake Mirror, and the direction home once more.",
  ui_story_40180001_191_dialog_content = "This is the legend as I heard it. It's called <color=#FFB400>The Child of the Lost Forest</color>.",
  ui_story_40180001_192_dialog_content = "And that's it.",
  ui_story_40180001_193_dialog_content = "That's... all?",
  ui_story_40180001_194_dialog_content = "Right. So, PlayerName, with regards to your obvious desire to know who this kid is and what's up with that forest...",
  ui_story_40180001_195_dialog_content = "Or any new questions you may have after hearing the legend, PlayerName, such as...",
  ui_story_40180001_A4_dialog_content = "Do the paths in that forest really change all the time? And why do they stop shifting when that kid shows up?",
  ui_story_40180001_196_dialog_content = "Unfortunately, <color=#FFB400>I don't have any answers for you</color>.",
  ui_story_40180001_197_dialog_content = "Legends are legends for a reason—they don't need to be explained.",
  ui_story_40180001_198_dialog_content = "That's a good point... and it's one worth thinking about.",
  ui_story_40180001_199_dialog_content = "It certainly holds some truth...",
  ui_story_40180001_200_dialog_content = "I also feel... It can be seen as a cautionary tale.",
  ui_story_40180001_201_dialog_content = "As a noble, one should make thorough inquiries... To the best of one's ability.",
  ui_story_40180001_202_dialog_content = "Hey! Why are you all so easily convinced!?",
  ui_story_40180001_203_dialog_content = "I'm even more confused now... and there's no way I can sleep!",
  ui_story_40180001_204_dialog_content = "Constantine! You think it's strange too, right!? There are still so many strange places in the world, and we need to investigate them in as much detail as possible, right!?",
  ui_story_40180001_205_dialog_content = "That's right! This whole thing is really very strange!",
  ui_story_40180001_206_dialog_content = "I know, right!?",
  ui_story_40180001_207_dialog_content = "If the forest paths were constantly changing, <color=#FFB400>why didn't I notice anything</color>?",
  ui_story_40180001_208_dialog_content = "Right!",
  ui_story_40180001_209_dialog_content = "And if this child really haunts the forest, that means the child's home is in the forest.",
  ui_story_40180001_A5_dialog_content = "But if the road keeps changing, how does the child get home?",
  ui_story_40180001_210_dialog_content = "Erm... Right!",
  ui_story_40180001_211_dialog_content = "And if the child can't get home, how can that little thing possibly have made a copy of my coat?",
  ui_story_40180001_212_dialog_content = "Erm... Yeah!",
  ui_story_40180001_213_dialog_content = "No, no, no... Sure enough, the coat that villager saw was merely an illusion. The child must still be shivering in the cold!",
  ui_story_40180001_214_dialog_content = "Huh?",
  ui_story_40180001_215_dialog_content = "There's no time to waste... I must go to Northland and bring that child something to wear!",
  ui_story_40180001_X215_dialog_content = "If he keeps going around like that, he will surely end up getting sick!",
  ui_story_40180001_216_dialog_content = "<size=36>You're really not getting this, are you...</size>"
}
return config
